graph-attention-network.pseudocode:
def gat_layer(h, neighbors, W, attn, leaky):
    # h[i]: 노드 특징, neighbors[i]: 이웃 집합
    out = {}
    for i in h:
        scores = {}
        for j in neighbors[i] | {i}:  # 자기 자신 포함
            e = attn(concat(W @ h[i], W @ h[j]))
            scores[j] = leaky(e)  # LeakyReLU
        alpha = softmax(scores)  # 이웃 간 정규화
        out[i] = sum(alpha[j] * (W @ h[j]) for j in scores)
    return out  # 멀티헤드는 이 과정을 K번 후 연결

greedy-best-first-search.pseudocode:
def greedy_bfs(start, goal, neighbors, h):
    import heapq
    frontier = [(h(start), start)]
    came_from = {start: None}
    while frontier:
        _, cur = heapq.heappop(frontier)  # h 최소 노드
        if cur == goal:
            return reconstruct(came_from, goal)
        for nxt in neighbors(cur):
            if nxt not in came_from:
                came_from[nxt] = cur
                # g(비용) 무시, 휴리스틱 h만으로 평가
                heapq.heappush(frontier, (h(nxt), nxt))
    return None  # 실패

grid-search.pseudocode:
def grid_search(grid, evaluate):
    # grid: {파라미터: [후보값...]}
    from itertools import product
    keys = list(grid)
    best_score, best_params = -1e18, None
    for combo in product(*(grid[k] for k in keys)):
        params = dict(zip(keys, combo))
        score = evaluate(params)  # 교차검증 점수
        if score > best_score:
            best_score, best_params = score, params
    return best_params, best_score
